import{_ as i,o as t,c as e,a5 as p}from"./chunks/framework.DJo0M80U.js";const d=JSON.parse('{"title":"解决vue修改数据页面不重新渲染问题(Vue中数组和对象更改后视图不刷新(转载)","description":"Luck Young 2020 07 07 15:08:10 219 收藏 1 分类专栏： 前端 Vue 版权 vue渲染机制和如何解决数据修改页面不刷新问题的多种方法 本文不讲原理，只讲干货易懂易学，(感觉能学到知识，麻烦给小编来个赞！) 1. 简单介绍一下Object.def。","frontmatter":{"title":"解决vue修改数据页面不重新渲染问题(Vue中数组和对象更改后视图不刷新(转载)","date":"2026-08-11T00:00:00.000Z","categories":["Vue 系统教程"],"tags":["Vue","Vue3","前端","教程","OneNote","项目实战"],"description":"Luck Young 2020 07 07 15:08:10 219 收藏 1 分类专栏： 前端 Vue 版权 vue渲染机制和如何解决数据修改页面不刷新问题的多种方法 本文不讲原理，只讲干货易懂易学，(感觉能学到知识，麻烦给小编来个赞！) 1. 简单介绍一下Object.def。","sidebarWeight":72,"lastUpdated":false,"feed":false,"source":"onenote","sourceNote":"OneNote/f-vue/实战/解决vue修改数据页面不重新渲染问题(Vue中数组和对象更改后视图不刷新(转载).md"},"headers":[],"relativePath":"posts/Vue系统教程/07-项目实战/解决vue修改数据页面不重新渲染问题(Vue中数组和对象更改后视图不刷新(转载).md","filePath":"posts/Vue系统教程/07-项目实战/解决vue修改数据页面不重新渲染问题(Vue中数组和对象更改后视图不刷新(转载).md"}'),a={name:"posts/Vue系统教程/07-项目实战/解决vue修改数据页面不重新渲染问题(Vue中数组和对象更改后视图不刷新(转载).md"};function s(r,l,o,c,u,n){return t(),e("div",null,[...l[0]||(l[0]=[p('<div><h1 id="解决vue修改数据页面不重新渲染问题-vue中数组和对象更改后视图不刷新-转载" tabindex="-1">解决vue修改数据页面不重新渲染问题(Vue中数组和对象更改后视图不刷新(转载) <a class="header-anchor" href="#解决vue修改数据页面不重新渲染问题-vue中数组和对象更改后视图不刷新-转载" aria-label="Permalink to &quot;解决vue修改数据页面不重新渲染问题(Vue中数组和对象更改后视图不刷新(转载)&quot;">​</a></h1><blockquote><p>本节目标：理解“解决vue修改数据页面不重新渲染问题(Vue中数组和对象更改后视图不刷新(转载)”的核心思路，并能把它用于实际开发或面试表达。</p></blockquote><blockquote><p>说明：原 OneNote 中有图片引用，但图片未包含在导出目录中；本页保留了可用的文字与代码内容。 <a href="https://me.csdn.net/Mote123" target="_blank" rel="noreferrer">Luck Young</a> 2020-07-07 15:08:10</p></blockquote><p>219</p><p>收藏 1 分类专栏： <a href="https://blog.csdn.net/mote123/category_9777605.html" target="_blank" rel="noreferrer">前端</a> <a href="https://blog.csdn.net/mote123/category_8979315.html" target="_blank" rel="noreferrer">Vue</a> 版权 <strong>vue渲染机制和如何解决数据修改页面不刷新问题的多种方法</strong> 本文不讲原理，只讲干货易懂易学，(感觉能学到知识，麻烦给小编来个赞！)</p><ol><li><p>简单介绍一下Object.definePropety,==Object.defineProperty(obj, prop, descriptor)========//参数========obj========要在其上定义属性的对象。========prop========要定义或修改的属性的名称。========descriptor========将被定义或修改的属性描述符========var obj = {}========Object.defineProperty(obj, &#39;name&#39;, {====== ==get: function() {====== ==console.log(&#39;我的名字叫&#39;+name);====== ==return name;====== ==},====== ==set: function(value) {====== ==console.log(&#39;你叫&#39;+value)====== ==name = value;====== ==}========});========obj.name =&#39;张三&#39;;==<em>//你叫张三</em>======obj.name==<em>//我的名字叫张三</em>====</p></li><li><p>==1==</p></li><li><p>==2==</p></li><li><p>==3==</p></li><li><p>==4==</p></li><li><p>==5==</p></li><li><p>==6==</p></li><li><p>==7==</p></li><li><p>==8==</p></li><li><p>==9==</p></li><li><p>==10==</p></li><li><p>==11==</p></li><li><p>==12==</p></li><li><p>==13==</p></li><li><p>因此在vue中写在data中的属性是是可以转换成getter和setter，换一句话就是响应式的，其他定义在data之外的数据，是无法响应的渲染，意思就是改变数据页面也不会刷新，所以一切要渲染到页面上的数据，必须写在data中，不需要的，可以定义在this上，==var vm = new Vue({====== ==data:{====== ==a:1====== ==}========})==========<em>// <code>vm.a</code> 是响应式的</em>==========vm.b = 2======<em>// <code>vm.b</code> 是非响应式的</em>====</p></li><li><p>==1==</p></li><li><p>==2==</p></li><li><p>==3==</p></li><li><p>==4==</p></li><li><p>==5==</p></li><li><p>==6==</p></li><li><p>==7==</p></li><li><p>==8==</p></li><li><p>==9==</p></li><li><p>==10==</p></li><li><p>简单介绍完了，我们来列举几个不刷新的实例当然上述也是一种第一种：修改对象的某一属性vue只会将已经在data中声明的属性变为响应，没有声明的是不响应的==&lt;template&gt;====== ==&lt;div&gt;====== ==&lt;div v-for=&#39;item in list&#39;&gt;{{item}}&lt;/div&gt;====== ==&lt;button @click=&#39;click&#39;&gt;改变&lt;/button&gt;====== ==&lt;button @click=&#39;hadelClick&#39;&gt;解决方法&lt;/button&gt;====== ==&lt;/div&gt;========&lt;/template&gt;========&lt;script&gt;====== ==export default({====== ==data(){====== ==return{====== ==list:{a:&#39;a&#39;,b:&#39;b&#39;},====== ==}====== ==},====== ==methods: {====== ==click() {====== <em>// 未声明不触发渲染</em>==== ==this.list.c=&#39;c&#39;============},====== ==hadelClick(){====== <em>// 解决方法，使用vue提供的$set方法来触发渲染</em>==== ==this.$set(this.list,&#39;d&#39;,&#39;d&#39;)====== ==}====== ==}====== ==})========&lt;/script&gt;======</p></li><li><p>==1==</p></li><li><p>==2==</p></li><li><p>==3==</p></li><li><p>==4==</p></li><li><p>==5==</p></li><li><p>==6==</p></li><li><p>==7==</p></li><li><p>==8==</p></li><li><p>==9==</p></li><li><p>==10==</p></li><li><p>==11==</p></li><li><p>==12==</p></li><li><p>==13==</p></li><li><p>==14==</p></li><li><p>==15==</p></li><li><p>==16==</p></li><li><p>==17==</p></li><li><p>==18==</p></li><li><p>==19==</p></li><li><p>==20==</p></li><li><p>==21==</p></li><li><p>==22==</p></li><li><p>==23==</p></li><li><p>==24==</p></li><li><p>==25==</p></li><li><p>==26==</p></li><li><p>==27======当然如果我们要添加多个属性，可以使用 Object.assign() 用于将所有可枚举属性的值从一个或多个源对象复制到目标对象，并返回目标对象。(简单说就是合并到第一个参数中)==this.list = Object.assign({},this.list,{c:&#39;c&#39;,d:&#39;d&#39;})======第二种：修改数组对象的某一属性==&lt;template&gt;====== ==&lt;div&gt;====== ==&lt;div v-for=&#39;item in list&#39;&gt;{{item.a}}&lt;/div&gt;====== ==&lt;button @click=&#39;click&#39;&gt;改变&lt;/button&gt;====== ==&lt;button @click=&#39;hadelClick&#39;&gt;解决方法&lt;/button&gt;====== ==&lt;/div&gt;========&lt;/template&gt;========&lt;script&gt;====== ==export default({====== ==data(){====== ==return{====== ==list:[{a:&#39;vue&#39;},{a:&#39;react&#39;},{a:&#39;js&#39;}],====== ==}====== ==},====== ==methods: {====== ==click() {====== <em>//想这样直接给数组中的某一个对象直接赋值，是无法动态渲染的（即改变了数据，页面不渲染）</em>==== ==this.list[0] = {a:&#39;css&#39;}== <em>//页面不渲染</em>==== ==console.log(this.list)== <em>//[{a:&#39;css&#39;},{a:&#39;react&#39;},{a:&#39;js&#39;}]</em>==== ==},====== ==hadelClick(){====== <em>// 解决方法，使用vue提供的$set方法来触发渲染</em>==== ==this.$set(this.list[1],&#39;a&#39;,&#39;css&#39;)====== ==console.log(this.list)==<em>//[{a:&#39;css&#39;},{a:&#39;css&#39;},{a:&#39;js&#39;}]</em>==== ==}====== ==}====== ==})========&lt;/script&gt;======</p></li><li><p>==1==</p></li><li><p>==2==</p></li><li><p>==3==</p></li><li><p>==4==</p></li><li><p>==5==</p></li><li><p>==6==</p></li><li><p>==7==</p></li><li><p>==8==</p></li><li><p>==9==</p></li><li><p>==10==</p></li><li><p>==11==</p></li><li><p>==12==</p></li><li><p>==13==</p></li><li><p>==14==</p></li><li><p>==15==</p></li><li><p>==16==</p></li><li><p>==17==</p></li><li><p>==18==</p></li><li><p>==19==</p></li><li><p>==20==</p></li><li><p>==21==</p></li><li><p>==22==</p></li><li><p>==23==</p></li><li><p>==24==</p></li><li><p>==25==</p></li><li><p>==26==</p></li><li><p>==27==</p></li><li><p>==28======当然前文讲过，vue会遍历data中的数据，将对象转换成setter和getter。所以数组中的也不例外，所以上述操作_// 改成：_======click(){====== ==this.list[0].a = css== <em>//依旧能够触发setter。实现数据重新渲染</em>==== ==}========}======</p></li><li><p>==1==</p></li><li><p>==2==</p></li><li><p>==3==</p></li><li><p>==4==</p></li><li><p>==5==</p></li></ol><p>在vue中更多的是数组的操作不刷新，一种是通过索引赋值，一种是修改数组长度，如何解决呢？ vue官方也给了方法 数组的API，中能够改变原始数组的都能触发更新； ==Array.push()========Array.pop()========Array.shift()========Array.unshift()========Array.splice()========Array.sort()========Array.reverse()======</p><ul><li>==1==</li><li>==2==</li><li>==3==</li><li>==4==</li><li>==5==</li><li>==6==</li><li>==7==</li></ul><p>第二种是返回一个新数组的，这种数组在引用地址上已经发生根本改变，这样的赋值操作是能触发更新的（这是处理不刷新的思路，就是改变引用地址，重新赋值触发更新） 简单说，用数组的API就是直接用原数组接收改变的数组， ==&lt;template&gt;====== ==&lt;div&gt;====== ==&lt;div v-for=&#39;item in list&#39;&gt;{{item.a}}&lt;/div&gt;====== ==&lt;button @click=&#39;click&#39;&gt;改变原数组&lt;/button&gt;====== ==&lt;button @click=&#39;hadelClick&#39;&gt;不改变原数组&lt;/button&gt;====== ==&lt;/div&gt;========&lt;/template&gt;========&lt;script&gt;====== ==export default({====== ==data(){====== ==return{====== ==list:[{a:&#39;vue&#39;},{a:&#39;react&#39;},{a:&#39;js&#39;}],====== ==}====== ==},====== ==methods: {====== ==click() {====== <em>//改变数组刷新页面</em>==== ==this.list.push({a:&#39;css&#39;})====== ==},====== ==hadelClick(){====== <em>//重新赋值刷新页面</em> ==== ==this.list = this.list.map(item=&gt;{====== ==item.a = &#39;css&#39;====== ==return item====== ==})====== ==}====== ==})========&lt;/script&gt;======</p><ul><li>==1==</li><li>==2==</li><li>==3==</li><li>==4==</li><li>==5==</li><li>==6==</li><li>==7==</li><li>==8==</li><li>==9==</li><li>==10==</li><li>==11==</li><li>==12==</li><li>==13==</li><li>==14==</li><li>==15==</li><li>==16==</li><li>==17==</li><li>==18==</li><li>==19==</li><li>==20==</li><li>==21==</li><li>==22==</li><li>==23==</li><li>==24==</li><li>==25==</li><li>==26==</li><li>==27==</li><li>==28==</li></ul><p>最后提供解决思路（以上都搞不定的话） 对象和数组都是引用传递，要变成新数组，来接受，就需要改变源， 第一种 ==let arr = []==<em>//新数组</em>======this.list.forEach(item=&gt;{== <em>//需要渲染的数组</em>==== <em>//执行你的操作，最后用放到arr中</em>==== ==arr.push(item)========})========this.list = arr== <em>//相当于返回一个新数组可以触发渲染</em>====</p><ul><li>==1==</li><li>==2==</li><li>==3==</li><li>==4==</li><li>==5==</li><li>==6==</li></ul><p>第二种 <em>//想要直接改变渲染数组中的数据，但没有渲染</em>====<em>//解决方法：</em>======let arr = this.list.slice(0);==<em>//深拷贝，（等价一个新的数组）</em>======arr.forEach(item=&gt;{====== <em>//执行你的操作</em>======})======<em>//赋值操作</em>======this.list = arr======</p><ul><li>==1==</li><li>==2==</li><li>==3==</li><li>==4==</li><li>==5==</li><li>==6==</li><li>==7==</li><li>==8==</li></ul><p>当然这里只是简单介绍了，有关深拷贝的详细介绍，请参看另一篇博文 <a href="https://blog.csdn.net/marendu/article/details/100032370" target="_blank" rel="noreferrer">js数组深拷贝详解</a> 上述如果都无法执行，但你的数据缺实修改了，可以使用this.$forceUpdate()方法 （强制刷新） <em>// this.$forceUpdate(); // 强制刷新</em>======&lt;template&gt;== ==== ==&lt;div&gt;====== ==&lt;div v-for=&#39;item in list&#39;&gt;{{item.a}}&lt;/div&gt;====== ==&lt;button @click=&#39;click&#39;&gt;改变&lt;/button&gt;====== ==&lt;button @click=&#39;hadelClick&#39;&gt;解决方法&lt;/button&gt;====== ==&lt;/div&gt;========&lt;/template&gt;========&lt;script&gt;====== ==export default({====== ==data(){====== ==return{====== ==list:[{a:&#39;vue&#39;},{a:&#39;react&#39;},{a:&#39;js&#39;}],====== ==}====== ==},====== ==methods: {====== ==click() {====== ==this.list[0] = {a:&#39;css&#39;}== <em>//页面不渲染</em>==== ==console.log(this.list)== <em>//[{a:&#39;css&#39;},{a:&#39;react&#39;},{a:&#39;js&#39;}]</em>==== ==},====== ==hadelClick(){====== ==this.list[0] = {a:&#39;css&#39;}== <em>//页面不渲染</em>==== ==console.log(this.list)== <em>//[{a:&#39;css&#39;},{a:&#39;react&#39;},{a:&#39;js&#39;}]</em>==== ==this.$forceUpdate();==<em>//强制刷新</em>==== ==}====== ==}====== ==})========&lt;/script&gt;======</p><ul><li>==1==</li><li>==2==</li><li>==3==</li><li>==4==</li><li>==5==</li><li>==6==</li><li>==7==</li><li>==8==</li><li>==9==</li><li>==10==</li><li>==11==</li><li>==12==</li><li>==13==</li><li>==14==</li><li>==15==</li><li>==16==</li><li>==17==</li><li>==18==</li><li>==19==</li><li>==20==</li><li>==21==</li><li>==22==</li><li>==23==</li><li>==24==</li><li>==25==</li><li>==26==</li><li>==27==</li><li>==28==</li></ul><p>———————————————— 版权声明：本文为CSDN博主「MmM豆」的原创文章，遵循CC 4.0 BY-SA版权协议，转载请附上原文出处链接及本声明。 原文链接：<a href="https://blog.csdn.net/marendu/article/details/93492642" target="_blank" rel="noreferrer">https://blog.csdn.net/marendu/article/details/93492642</a> &gt; 来自 &lt;<a href="https://blog.csdn.net/Mote123/article/details/107181531/?utm_medium=distribute.pc_relevant.none-task-blog-baidujs-3" target="_blank" rel="noreferrer">https://blog.csdn.net/Mote123/article/details/107181531/?utm_medium=distribute.pc_relevant.none-task-blog-baidujs-3</a>&gt;</p><p>首先 第一点，vue底层是 将data对象传人，使用Object.definePropety,转换为getter和setter，所以，vue不支持IE8. 从上述我们可以简单发现。当我们对这个对象的name属性赋值的时候，就会触发set方法，获取name属性的时候就会触发get方法； &gt; 来自 &lt;<a href="https://blog.csdn.net/Mote123/article/details/107181531/?utm_medium=distribute.pc_relevant.none-task-blog-baidujs-3" target="_blank" rel="noreferrer">https://blog.csdn.net/Mote123/article/details/107181531/?utm_medium=distribute.pc_relevant.none-task-blog-baidujs-3</a>&gt;</p></div>',1)])])}const g=i(a,[["render",s]]);export{d as __pageData,g as default};
